//! Standard library documentation pages (`/stdlib` and `/stdlib/{module}`).
//!
//! Renders the modules, operator/function signatures, doc comments, and
//! examples loaded from `AEVIA_STDLIB_DOCS_DIR` (`stdlib-docs.json` or
//! Markdown files generated by `aevia doc --stdlib`).

use aevia_registry_core::Lang;
use aevia_registry_core::vm::StdlibBook;
use aevia_registry_core::vm::StdlibItem;
use aevia_registry_core::vm::StdlibModule;
use aevia_registry_core::vm::Viewer;
use leptos::prelude::AnyView;
use leptos::prelude::IntoAny;
use leptos::prelude::*;

use crate::Msg;
use crate::layout;
use crate::thousands;

const TITLE: Msg = Msg::new("standard library", "标准库");
const LEDE: Msg = Msg::new(
    "Built-in modules, operators, functions, dimensions, and physical units.",
    "内置模块、运算符、函数、量纲与物理单位。",
);
const NO_STDLIB: Msg = Msg::new(
    "Standard library documentation is not mounted on this deployment. Set \
     AEVIA_STDLIB_DOCS_DIR to the directory generated by `aevia doc --stdlib`.",
    "本次部署没有挂载标准库文档。请把 AEVIA_STDLIB_DOCS_DIR 指向 `aevia doc --stdlib` 生成的目录。",
);
const MODULES: Msg = Msg::new("modules", "模块");
const MODULE_COLUMN: Msg = Msg::new("module", "模块");
const SUMMARY_COLUMN: Msg = Msg::new("summary", "简介");
const ITEMS_COLUMN: Msg = Msg::new("items", "条目");
const ALL_MODULES: Msg = Msg::new("← all modules", "← 全部模块");
const EXAMPLES: Msg = Msg::new("examples", "示例");
const NO_ITEMS: Msg = Msg::new(
    "This module has no documented items yet.",
    "该模块尚无已记录的条目。",
);

/// Renders `/stdlib`.
#[must_use]
pub fn stdlib_index(
    book: &StdlibBook,
    lang: Lang,
    viewer: Option<&Viewer>,
) -> String {
    if book.modules.is_empty() {
        return layout::page(
            lang,
            TITLE.of(lang),
            "/stdlib",
            viewer,
            view! {
                <section class="empty-page">
                    <h1>{TITLE.of(lang)}</h1>
                    <p>{NO_STDLIB.of(lang)}</p>
                </section>
            },
        );
    }

    let module_count = thousands(i64::try_from(book.modules.len()).unwrap_or(0));
    let item_count = thousands(i64::try_from(book.total_items()).unwrap_or(0));
    let version = (!book.version.is_empty()).then(|| {
        let ver = book.version.clone();
        view! { <code>{ver}</code> }.into_any()
    });

    let rows: Vec<AnyView> = book
        .modules
        .iter()
        .map(|module| {
            let href = format!("/stdlib/{}", module.slug);
            let name = module.name.clone();
            let summary = module.summary.clone().unwrap_or_default();
            let count = thousands(i64::try_from(module.items.len()).unwrap_or(0));
            view! {
                <tr>
                    <td><a href=href>{name}</a></td>
                    <td class="muted">{summary}</td>
                    <td class="num">{count}</td>
                </tr>
            }
            .into_any()
        })
        .collect();

    layout::page(
        lang,
        TITLE.of(lang),
        "/stdlib",
        viewer,
        view! {
            <section class="page-head">
                <h1>{TITLE.of(lang)}</h1>
                <p>{LEDE.of(lang)}</p>
                <p class="small muted">
                    {version}
                    {if !book.version.is_empty() { " · " } else { "" }}
                    {format!("{module_count} {} · {item_count} {}", MODULES.of(lang), ITEMS_COLUMN.of(lang))}
                </p>
            </section>
            <table class="data-table">
                <thead>
                    <tr>
                        <th>{MODULE_COLUMN.of(lang)}</th>
                        <th>{SUMMARY_COLUMN.of(lang)}</th>
                        <th class="num">{ITEMS_COLUMN.of(lang)}</th>
                    </tr>
                </thead>
                <tbody>{rows}</tbody>
            </table>
        },
    )
}

/// Renders `/stdlib/{module}`.
#[must_use]
pub fn stdlib_module(
    book: &StdlibBook,
    module: &StdlibModule,
    lang: Lang,
    viewer: Option<&Viewer>,
) -> String {
    let current_slug = module.slug.clone();
    let sidebar_links: Vec<AnyView> = book
        .modules
        .iter()
        .map(|entry| {
            let current = (entry.slug == current_slug).then_some("page");
            let href = format!("/stdlib/{}", entry.slug);
            view! {
                <li>
                    <a href=href aria-current=current>{entry.name.clone()}</a>
                </li>
            }
            .into_any()
        })
        .collect();

    let summary_view = module.summary.as_ref().map(|summary| {
        let text = summary.clone();
        view! { <p class="lede">{text}</p> }.into_any()
    });

    let prose_view = (!module.html.is_empty()).then(|| {
        let html = module.html.clone();
        view! { <div class="markdown" inner_html=html></div> }.into_any()
    });

    let items_view = if module.items.is_empty() && module.html.is_empty() {
        view! { <p class="muted">{NO_ITEMS.of(lang)}</p> }.into_any()
    } else if module.items.is_empty() {
        view! { <div></div> }.into_any()
    } else {
        let cards: Vec<AnyView> = module
            .items
            .iter()
            .map(|item| render_item(lang, item))
            .collect();
        view! { <div class="stdlib-items">{cards}</div> }.into_any()
    };

    let page_title = format!("{} · {}", module.name, TITLE.of(lang));
    let module_name = module.name.clone();

    layout::page(
        lang,
        &page_title,
        "/stdlib",
        viewer,
        view! {
            <div class="docs-layout">
                <aside class="docs-side">
                    <p><a href="/stdlib">{ALL_MODULES.of(lang)}</a></p>
                    <h2>{MODULES.of(lang)}</h2>
                    <ul>{sidebar_links}</ul>
                </aside>
                <article class="docs-body">
                    <header class="page-head">
                        <h1>{module_name}</h1>
                        {summary_view}
                    </header>
                    {prose_view}
                    {items_view}
                </article>
            </div>
        },
    )
}

fn render_item(
    lang: Lang,
    item: &StdlibItem,
) -> AnyView {
    let kind = (!item.kind.is_empty()).then(|| {
        let kind = item.kind.clone();
        view! { <span class="stdlib-kind">{kind}</span> }.into_any()
    });
    let name = item.name.clone();
    let sig = (!item.signature.is_empty()).then(|| {
        let sig = item.signature.clone();
        view! { <pre class="stdlib-sig"><code>{sig}</code></pre> }.into_any()
    });
    let doc = (!item.doc_html.is_empty()).then(|| {
        let html = item.doc_html.clone();
        view! { <div class="markdown" inner_html=html></div> }.into_any()
    });
    let examples = (!item.examples.is_empty()).then(|| {
        let blocks: Vec<AnyView> = item
            .examples
            .iter()
            .map(|ex| {
                let code = ex.clone();
                view! { <pre class="code"><code>{code}</code></pre> }.into_any()
            })
            .collect();
        view! {
            <div class="stdlib-examples">
                <h4>{EXAMPLES.of(lang)}</h4>
                {blocks}
            </div>
        }
        .into_any()
    });

    view! {
        <section class="stdlib-item" id=item.name.clone()>
            <div class="stdlib-item-head">
                {kind}
                <h3>{name}</h3>
            </div>
            {sig}
            {doc}
            {examples}
        </section>
    }
    .into_any()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_book() -> StdlibBook {
        StdlibBook {
            version: "0.1.0".to_string(),
            modules: vec![StdlibModule {
                name: "Prelude".to_string(),
                slug: "Prelude".to_string(),
                summary: Some("Core functions and operators.".to_string()),
                html: String::new(),
                items: vec![StdlibItem {
                    kind: "fn".to_string(),
                    name: "sqrt".to_string(),
                    signature: "fn sqrt(x: Real[D]): Real[D^(1/2)]".to_string(),
                    doc: Some("Square root with half-dimension.".to_string()),
                    doc_html: "<p>Square root with half-dimension.</p>".to_string(),
                    examples: vec!["sqrt(4 m^2) == 2 m".to_string()],
                }],
            }],
        }
    }

    #[test]
    fn empty_stdlib_shows_mount_notice() {
        let html = stdlib_index(&StdlibBook::default(), Lang::En, None);
        assert!(html.contains("AEVIA_STDLIB_DOCS_DIR"));
    }

    #[test]
    fn stdlib_index_and_module_render_items() {
        let book = sample_book();
        let index_html = stdlib_index(&book, Lang::En, None);
        assert!(index_html.contains("/stdlib/Prelude"));
        assert!(index_html.contains("Core functions and operators."));

        let mod_html = stdlib_module(&book, &book.modules[0], Lang::En, None);
        assert!(mod_html.contains("fn sqrt(x: Real[D]): Real[D^(1/2)]"));
        assert!(mod_html.contains("Square root with half-dimension."));
        assert!(mod_html.contains("sqrt(4 m^2) == 2 m"));
    }
}
